import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    info = {}  # id -> {'side','price','qty','active'}
    seq_counter = [0]

    def next_seq():
        seq_counter[0] += 1
        return seq_counter[0]

    def clean_buy_top():
        while buy_heap:
            negp, s, oid = buy_heap[0]
            od = info.get(oid)
            if od is None or not od['active'] or od['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            return (negp, s, oid)
        return None

    def clean_sell_top():
        while sell_heap:
            p, s, oid = sell_heap[0]
            od = info.get(oid)
            if od is None or not od['active'] or od['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            return (p, s, oid)
        return None

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            od = info.get(oid)
            if od is not None and od['active'] and od['qty'] > 0:
                od['active'] = False
            continue

        if typ == 'market':
            _, oid, side, qty = order
            price_limit = None
        else:
            _, oid, side, price, qty = order
            price_limit = price

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                top = clean_sell_top()
                if top is None:
                    break
                p, s, sell_id = top
                if price_limit is not None and typ != 'market' and p > price_limit:
                    break
                od = info[sell_id]
                trade_qty = min(remaining, od['qty'])
                trades.append([oid, sell_id, p, trade_qty])
                remaining -= trade_qty
                od['qty'] -= trade_qty
                if od['qty'] <= 0:
                    od['active'] = False
                    heapq.heappop(sell_heap)
                # if od still has qty>0, leave it at top of heap (don't pop)
                else:
                    # it stays as top, but since qty reduced, order stays same position
                    pass
                if od['qty'] <= 0:
                    continue
                else:
                    # top order still has qty left but remaining might be 0 now
                    if remaining <= 0:
                        break
                    else:
                        # this shouldn't happen since trade_qty = min(remaining, od['qty'])
                        # if remaining >0 after trade, od['qty'] must be 0
                        break

            if typ == 'limit' and remaining > 0:
                s = next_seq()
                info[oid] = {'side': 'buy', 'price': price_limit, 'qty': remaining, 'active': True}
                heapq.heappush(buy_heap, (-price_limit, s, oid))
            # ioc/market: discard remainder, do nothing

        else:  # side == 'sell'
            while remaining > 0:
                top = clean_buy_top()
                if top is None:
                    break
                negp, s, buy_id = top
                p = -negp
                if price_limit is not None and typ != 'market' and p < price_limit:
                    break
                od = info[buy_id]
                trade_qty = min(remaining, od['qty'])
                trades.append([buy_id, oid, p, trade_qty])
                remaining -= trade_qty
                od['qty'] -= trade_qty
                if od['qty'] <= 0:
                    od['active'] = False
                    heapq.heappop(buy_heap)
                if od['qty'] <= 0:
                    continue
                else:
                    if remaining <= 0:
                        break
                    else:
                        break

            if typ == 'limit' and remaining > 0:
                s = next_seq()
                info[oid] = {'side': 'sell', 'price': price_limit, 'qty': remaining, 'active': True}
                heapq.heappush(sell_heap, (price_limit, s, oid))

    return trades

